/**
 * @suppress
 */
public object FfiConverterString: FfiConverter<String, RustBuffer.ByValue> {
    // Note: we don't inherit from FfiConverterRustBuffer, because we use a
    // special encoding when lowering/lifting.  We can use `RustBuffer.len` to
    // store our length and avoid writing it out to the buffer.
    override fun lift(value: RustBuffer.ByValue): String {
        try {
            val byteArr = ByteArray(value.len.toInt())
            value.asByteBuffer()!!.get(byteArr)
            return byteArr.toString(Charsets.UTF_8)
        } finally {
            RustBuffer.free(value)
        }
    }

    override fun read(buf: ByteBuffer): String {
        val len = buf.getInt()
        val byteArr = ByteArray(len)
        buf.get(byteArr)
        return byteArr.toString(Charsets.UTF_8)
    }

    fun toUtf8(value: String): ByteBuffer {
        // Make sure we don't have invalid UTF-16, check for lone surrogates.
        return Charsets.UTF_8.newEncoder().run {
            onMalformedInput(CodingErrorAction.REPORT)
            encode(CharBuffer.wrap(value))
        }
    }

    override fun lower(value: String): RustBuffer.ByValue {
        val byteBuf = toUtf8(value)
        // Ideally we'd pass these bytes to `ffi_bytebuffer_from_bytes`, but doing so would require us
        // to copy them into a JNA `Memory`. So we might as well directly copy them into a `RustBuffer`.
        val rbuf = RustBuffer.alloc(byteBuf.limit().toULong())
        rbuf.asByteBuffer()!!.put(byteBuf)
        return rbuf
    }

    // We aren't sure exactly how many bytes our string will be once it's UTF-8
    // encoded.  Allocate 3 bytes per UTF-16 code unit which will always be
    // enough.
    override fun allocationSize(value: String): ULong {
        val sizeForLength = 4UL
        val sizeForString = value.length.toULong() * 3UL
        return sizeForLength + sizeForString
    }

    override fun write(value: String, buf: ByteBuffer) {
        val byteBuf = toUtf8(value)
        buf.putInt(byteBuf.limit())
        buf.put(byteBuf)
    }
}

/**
 * @suppress
 */
public object FfiConverterByteArray: FfiConverterRustBuffer<ByteArray> {
    override fun read(buf: ByteBuffer): ByteArray {
        val len = buf.getInt()
        val byteArr = ByteArray(len)
        buf.get(byteArr)
        return byteArr
    }
    override fun allocationSize(value: ByteArray): ULong {
        return 4UL + value.size.toULong()
    }
    override fun write(value: ByteArray, buf: ByteBuffer) {
        buf.putInt(value.size)
        buf.put(value)
    }
}


// This template implements a class for working with a Rust struct via a Pointer/Arc<T>
// to the live Rust struct on the other side of the FFI.
//
// Each instance implements core operations for working with the Rust `Arc<T>` and the
// Kotlin Pointer to work with the live Rust struct on the other side of the FFI.
//
// There's some subtlety here, because we have to be careful not to operate on a Rust
// struct after it has been dropped, and because we must expose a public API for freeing
// theq Kotlin wrapper object in lieu of reliable finalizers. The core requirements are:
//
//   * Each instance holds an opaque pointer to the underlying Rust struct.
//     Method calls need to read this pointer from the object's state and pass it in to
//     the Rust FFI.
//
//   * When an instance is no longer needed, its pointer should be passed to a
//     special destructor function provided by the Rust FFI, which will drop the
//     underlying Rust struct.
//
//   * Given an instance, calling code is expected to call the special
//     `destroy` method in order to free it after use, either by calling it explicitly
//     or by using a higher-level helper like the `use` method. Failing to do so risks
//     leaking the underlying Rust struct.
//
//   * We can't assume that calling code will do the right thing, and must be prepared
//     to handle Kotlin method calls executing concurrently with or even after a call to
//     `destroy`, and to handle multiple (possibly concurrent!) calls to `destroy`.
//
//   * We must never allow Rust code to operate on the underlying Rust struct after
//     the destructor has been called, and must never call the destructor more than once.
//     Doing so may trigger memory unsafety.
//
//   * To mitigate many of the risks of leaking memory and use-after-free unsafety, a `Cleaner`
//     is implemented to call the destructor when the Kotlin object becomes unreachable.
//     This is done in a background thread. This is not a panacea, and client code should be aware that
//      1. the thread may starve if some there are objects that have poorly performing
//     `drop` methods or do significant work in their `drop` methods.
//      2. the thread is shared across the whole library. This can be tuned by using `android_cleaner = true`,
//         or `android = true` in the [`kotlin` section of the `uniffi.toml` file](https://mozilla.github.io/uniffi-rs/kotlin/configuration.html).
//
// If we try to implement this with mutual exclusion on access to the pointer, there is the
// possibility of a race between a method call and a concurrent call to `destroy`:
//
//    * Thread A starts a method call, reads the value of the pointer, but is interrupted
//      before it can pass the pointer over the FFI to Rust.
//    * Thread B calls `destroy` and frees the underlying Rust struct.
//    * Thread A resumes, passing the already-read pointer value to Rust and triggering
//      a use-after-free.
//
// One possible solution would be to use a `ReadWriteLock`, with each method call taking
// a read lock (and thus allowed to run concurrently) and the special `destroy` method
// taking a write lock (and thus blocking on live method calls). However, we aim not to
// generate methods with any hidden blocking semantics, and a `destroy` method that might
// block if called incorrectly seems to meet that bar.
//
// So, we achieve our goals by giving each instance an associated `AtomicLong` counter to track
// the number of in-flight method calls, and an `AtomicBoolean` flag to indicate whether `destroy`
// has been called. These are updated according to the following rules:
//
//    * The initial value of the counter is 1, indicating a live object with no in-flight calls.
//      The initial value for the flag is false.
//
//    * At the start of each method call, we atomically check the counter.
//      If it is 0 then the underlying Rust struct has already been destroyed and the call is aborted.
//      If it is nonzero them we atomically increment it by 1 and proceed with the method call.
//
//    * At the end of each method call, we atomically decrement and check the counter.
//      If it has reached zero then we destroy the underlying Rust struct.
//
//    * When `destroy` is called, we atomically flip the flag from false to true.
//      If the flag was already true we silently fail.
//      Otherwise we atomically decrement and check the counter.
//      If it has reached zero then we destroy the underlying Rust struct.
//
// Astute readers may observe that this all sounds very similar to the way that Rust's `Arc<T>` works,
// and indeed it is, with the addition of a flag to guard against multiple calls to `destroy`.
//
// The overall effect is that the underlying Rust struct is destroyed only when `destroy` has been
// called *and* all in-flight method calls have completed, avoiding violating any of the expectations
// of the underlying Rust code.
//
// This makes a cleaner a better alternative to _not_ calling `destroy()` as
// and when the object is finished with, but the abstraction is not perfect: if the Rust object's `drop`
// method is slow, and/or there are many objects to cleanup, and it's on a low end Android device, then the cleaner
// thread may be starved, and the app will leak memory.
//
// In this case, `destroy`ing manually may be a better solution.
//
// The cleaner can live side by side with the manual calling of `destroy`. In the order of responsiveness, uniffi objects
// with Rust peers are reclaimed:
//
// 1. By calling the `destroy` method of the object, which calls `rustObject.free()`. If that doesn't happen:
// 2. When the object becomes unreachable, AND the Cleaner thread gets to call `rustObject.free()`. If the thread is starved then:
// 3. The memory is reclaimed when the process terminates.
//
// [1] https://stackoverflow.com/questions/24376768/can-java-finalize-an-object-when-it-is-still-in-scope/24380219
//


/**
 * The cleaner interface for Object finalization code to run.
 * This is the entry point to any implementation that we're using.
 *
 * The cleaner registers objects and returns cleanables, so now we are
 * defining a `UniffiCleaner` with a `UniffiClenaer.Cleanable` to abstract the
 * different implmentations available at compile time.
 *
 * @suppress
 */
interface UniffiCleaner {
    interface Cleanable {
        fun clean()
    }

    fun register(value: Any, cleanUpTask: Runnable): UniffiCleaner.Cleanable

    companion object
}

// The fallback Jna cleaner, which is available for both Android, and the JVM.
private class UniffiJnaCleaner : UniffiCleaner {
    private val cleaner = com.sun.jna.internal.Cleaner.getCleaner()

    override fun register(value: Any, cleanUpTask: Runnable): UniffiCleaner.Cleanable =
        UniffiJnaCleanable(cleaner.register(value, cleanUpTask))
}

private class UniffiJnaCleanable(
    private val cleanable: com.sun.jna.internal.Cleaner.Cleanable,
) : UniffiCleaner.Cleanable {
    override fun clean() = cleanable.clean()
}

// We decide at uniffi binding generation time whether we were
// using Android or not.
// There are further runtime checks to chose the correct implementation
// of the cleaner.


private fun UniffiCleaner.Companion.create(): UniffiCleaner =
    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.UPSIDE_DOWN_CAKE) {
        AndroidSystemCleaner()
    } else {
        UniffiJnaCleaner()
    }

// The SystemCleaner, available from API Level 33.
// Some API Level 33 OSes do not support using it, so we require API Level 34.
@RequiresApi(Build.VERSION_CODES.UPSIDE_DOWN_CAKE)
private class AndroidSystemCleaner : UniffiCleaner {
    val cleaner = android.system.SystemCleaner.cleaner()

    override fun register(value: Any, cleanUpTask: Runnable): UniffiCleaner.Cleanable =
        AndroidSystemCleanable(cleaner.register(value, cleanUpTask))
}

@RequiresApi(Build.VERSION_CODES.UPSIDE_DOWN_CAKE)
private class AndroidSystemCleanable(
    private val cleanable: java.lang.ref.Cleaner.Cleanable,
) : UniffiCleaner.Cleanable {
    override fun clean() = cleanable.clean()
}
/**
 * Opaque handle to a single loaded Tride scene.
 *
 * Owns the parsed `.trd` archive, the compiled bindings engine, the
 * state machine, the mutable glTF document, the view-model value store, and
 * the fixed-step clock state. Cloned freely (cheap `Arc`); concurrent
 * access is serialised by an internal `Mutex` (see crate-level docs).
 *
 * The `last_tick_ns` field is the FFI-side translation of the
 * `dt_ms`-style API exposed to Swift / Kotlin into the monotonic
 * `now_ns` timeline that `tride-runtime-api::RuntimeHandle::tick`
 * expects. We keep it in this crate so that `tride-runtime-api`
 * stays untouched.
 */
public interface TrideSceneInterface {
    
    /**
     * Authored active camera slug (`manifest.scene.active_camera`).
     * `None` = the host keeps its default viewport camera. Runtime
     * switches arrive as `/scene/active_camera` mutations in [`Self::tick`];
     * this is the load-time seed.
     */
    fun `activeCamera`(): kotlin.String?
    
    /**
     * Replay a host script from this scene's clock: the steps as
     * JSON (`[{deltaMs, inputs?}, {until, maxMs}, …]`), the final state back — plant geometry
     * evaluated once at the end. Scene events reach `subscribe_events` as the ticks run. A script
     * that stops early (or is not a script) reports it in the result, not as an error.
     *
     * # Errors
     * [`TrideError::Internal`] only on mutex poisoning.
     */
    fun `advance`(`scriptJson`: kotlin.String): AdvanceResult
    
    /**
     * The next interleaved PCM of `input`, its first sample sounding at `start_time_s` of the
     * input's audio time (a track from 0; a stream: the player's presentation time).
     *
     * # Errors
     * [`TrideError::InvalidAudio`] for an input that was never begun.
     */
    fun `appendAudio`(`input`: kotlin.String, `startTimeS`: kotlin.Double, `pcm`: List<kotlin.Float>)
    
    /**
     * Raw bytes of an archive asset (`assets/…`, e.g. the image behind
     * [`TrideTextureRef::uri`]); `None` when the path is not in the archive, or only an older
     * file's glTF carrier named it (one notice).
     */
    fun `assetBytes`(`uri`: kotlin.String): kotlin.ByteArray?
    
    /**
     * The scene's background behind everything when no skybox is drawn — no environment, or
     * `background_visible: false`: linear RGB, length 3, the schema's grey when not
     * authored. Separate from [`Self::environment`], which is `None` exactly when this matters
     * most. Its animation arrives as `/environment_settings/background_color` mutations.
     */
    fun `backgroundColor`(): List<kotlin.Double>
    
    /**
     * Start audio input `input` (a slug: the scene reads it as `audio.<input>.<probe>`):
     * interleaved `f32` PCM of `channels` channels at `sample_rate` Hz. Starting a begun input
     * again drops what it had.
     *
     * # Errors
     * [`TrideError::InvalidAudio`] for a name that is no slug or a zero rate / channel count.
     */
    fun `beginAudio`(`input`: kotlin.String, `sampleRate`: kotlin.UInt, `channels`: kotlin.UShort, `kind`: TrideAudioKind)
    
    /**
     * Bind host source `source` to the scene's number input `input`: from the next tick on the
     * runtime writes it as `mapping` maps the source (defaults when `None`: the speed 0…2
     * screens / s, the position 0…1, onto 0…1); `set_binding` on it is then refused. Binding it
     * again replaces the binding; `reset` keeps it.
     *
     * # Errors
     * [`TrideError::InvalidBinding`] for an input the scene lacks, not a number, computed or
     * written by a scene drive, or a mapping with an empty source range or a number that is not
     * finite; [`TrideError::Internal`] on mutex poisoning.
     */
    fun `bindInput`(`input`: kotlin.String, `source`: TrideInputSource, `mapping`: TrideInputMapping?)
    
    /**
     * The host's bindings, in the order they were made (none when the runtime is unreachable).
     */
    fun `boundInputs`(): List<TrideBoundInput>
    
    /**
     * Image input `name` back to no picture: `empty`.
     *
     * # Errors
     * [`TrideError::InvalidImage`] for a name that is no image input.
     */
    fun `clearImage`(`name`: kotlin.String)
    
    /**
     * Currently-active state name (e.g. `"idle"`, `"running"`) of the LAST layer — hosts rely
     * on this; per-layer state is [`Self::layer_current_state`].
     */
    fun `currentState`(): kotlin.String
    
    /**
     * Datablock `uid` decoded into flat triangle streams + the palette entry of its
     * material — the mesh the host instances at every module frame (data-texture
     * instancing); a parametric datablock at its effective recipe
     * (pull again after `/datablocks/{uid}/geometry`). `None` when the uid is
     * unknown / malformed or the decode fails (the host logs it). A view built again reads every
     * mesh. The one core path the WASM `RuntimeHandle.datablockMesh` takes too
     * (`tride_runtime_api::SourceData::datablock_mesh`).
     */
    fun `datablockMesh`(`uid`: kotlin.String): TrideDatablockMesh?
    
    /**
     * The camera to draw through while the scene has no active camera, for a view `aspect`
     * wide (width / height). Ask at load and when the aspect changes; keep no own framing rule.
     *
     * # Errors
     * [`TrideError::Internal`] only on mutex poisoning.
     */
    fun `defaultFraming`(`aspect`: kotlin.Double): TrideDefaultFraming
    
    /**
     * Default render settings (all Filament defaults). iOS hosts can use
     * this as a starting point, then customize individual fields before
     * passing to `FilamentBridge.applyRenderSettings()`.
     */
    fun `defaultRenderSettings`(): TrideRenderSettings
    
    /**
     * The bent mesh of node `node_uid` — pull it after a
     * `/deformed/{node_uid}/geometry` announcement with `active: true`; the streams and look as
     * [`Self::datablock_mesh`] gives them (the node's datablock bent by its deformers). `None` =
     * no deformer reaches the node: the host draws its own mesh.
     */
    fun `deformedMesh`(`nodeUid`: kotlin.String): TrideDatablockMesh?
    
    /**
     * The view axes the scene's drag interactions claim (none when the runtime is unreachable).
     */
    fun `dragAxes`(): TrideDragAxes
    
    /**
     * Emit a declared outgoing event (same contract as
     * `tride_runtime_api::RuntimeHandle::emit_event`). Trigger fields
     * (D6) use an empty `payload` map.
     */
    fun `emitEvent`(`name`: kotlin.String, `payload`: Map<kotlin.String, TrideValue>)
    
    /**
     * A track is complete: silence follows its tail (a stream ignores it).
     *
     * # Errors
     * [`TrideError::InvalidAudio`] for an input that was never begun.
     */
    fun `endAudio`(`input`: kotlin.String)
    
    /**
     * Authored HDR environment from `manifest.scene.environment` +
     * `manifest.environment_settings`. `None` when the
     * scene declares no environment. Byte-faithful with the manifest; the iOS
     * bridge enumerates at load to build the Filament `IndirectLight` + skybox
     * (preset → bundled KTX, custom → `.trd` `assets/ibl/<uid>_*.ktx`).
     */
    fun `environment`(): TrideEnvironmentDescriptor?
    
    /**
     * Alias for [`Self::trigger`] — editor naming; `trigger` kept for existing Swift.
     */
    fun `fireTrigger`(`name`: kotlin.String)
    
    /**
     * Trunk geometry of generator `id` at its current epoch, or `None`
     * when the id is unknown / the recipe failed to evaluate (see tick diagnostics).
     */
    fun `generatedGeometry`(`id`: kotlin.String): TrideGeneratedGeometry?
    
    /**
     * Pulse table of generator `id`; `None` = nothing to draw.
     */
    fun `generatorFlow`(`id`: kotlin.String): TridePulseTable?
    
    /**
     * Module frames (datablock-bound symbols) of generator `id`; empty when unknown.
     */
    fun `generatorFrames`(`id`: kotlin.String): List<TrideModuleFrame>
    
    /**
     * The instance row of every instance drawn under `symbol`: little-endian IEEE
     * binary16, `R G B value` per instance (8 bytes), in the order of
     * [`Self::generator_module_transforms`] — the colour and value the cloner's effectors with
     * Color Mode «Fields Color» left on each clone; white / 1 per instance where none colours.
     * Pull it with the transforms; a host whose material reads it ([`TrideMaterialGraph`]
     * `instance_colors`) uploads it verbatim as the RGBA16F `instanceColors` texture.
     */
    fun `generatorModuleColors`(`id`: kotlin.String, `symbol`: kotlin.String): kotlin.ByteArray
    
    /**
     * Flat column-major `mat4[]` (LE `f32`, 64 bytes per instance) of the instances drawn
     * under `symbol` (the instance buffer contract): an L-system module symbol or, for a
     * cloner, a datablock uid (`modules[].symbol` of the descriptor); empty when unknown.
     * The host uploads it verbatim as the instance data texture.
     */
    fun `generatorModuleTransforms`(`id`: kotlin.String, `symbol`: kotlin.String): kotlin.ByteArray
    
    /**
     * Read the current view-model value (see [`tride_runtime_api::RuntimeHandle::get_binding`]).
     */
    fun `getBinding`(`name`: kotlin.String): TrideValue
    
    /**
     * The host could not get a picture for `name` (decode, network): `failed`, the placeholder
     * stays.
     *
     * # Errors
     * [`TrideError::InvalidImage`] for a name that is no image input.
     */
    fun `imageFailed`(`name`: kotlin.String, `reason`: kotlin.String)
    
    /**
     * Image input `name` as the host left it; `None` for a name that is no image input.
     */
    fun `imageInput`(`name`: kotlin.String): TrideImageInput?
    
    /**
     * The host is fetching or decoding a picture for `name`: `loading`, the placeholder shows.
     *
     * # Errors
     * [`TrideError::InvalidImage`] for a name that is no image input.
     */
    fun `imageLoading`(`name`: kotlin.String)
    
    /**
     * Every input of the scene and the values `set_inputs_json` takes now, as JSON
     * `{"inputs":[{name, kind, value, default, options?, min?, max?, maxLength?, multiline?,
     * computed?, doc?, settings?}], "values":{name: value}}` — the same bytes on every host.
     *
     * # Errors
     * [`TrideError::Internal`] on mutex poisoning or a JSON encode failure.
     */
    fun `inputsJson`(): kotlin.String
    
    /**
     * Number of SM layers (`0` for an SM-less scene).
     */
    fun `layerCount`(): kotlin.UInt
    
    /**
     * Current state of the layer at `index`.
     */
    fun `layerCurrentState`(`index`: kotlin.UInt): kotlin.String?
    
    /**
     * Slug of the layer at `index` — what [`TrideStateChange::layer_id`] carries.
     */
    fun `layerId`(`index`: kotlin.UInt): kotlin.String?
    
    /**
     * Human-readable name of the layer at `index`.
     */
    fun `layerName`(`index`: kotlin.UInt): kotlin.String?
    
    /**
     * List all declared view-model bindings (name + kind).
     */
    fun `listBindings`(): List<TrideBindingDescriptor>
    
    /**
     * List all authored cameras from `manifest.cameras[]`.
     * Byte-faithful with [`tride_runtime_api::RuntimeHandle::manifest`];
     * empty for legacy `.trd` archives without cameras. iOS hosts
     * enumerate at load and drive `view->setCamera` on the active slug.
     */
    fun `listCameras`(): List<TrideCameraDescriptor>
    
    /**
     * Uids of every node drawn bent now.
     */
    fun `listDeformedNodes`(): List<kotlin.String>
    
    /**
     * Authored procedural generators — one per
     * `manifest.generators[]`; hosts pair each with its hosting node via `node_uid`.
     */
    fun `listGenerators`(): List<TrideGeneratorDescriptor>
    
    /**
     * List all authored lights from `manifest.lights[]`.
     * Byte-faithful with [`tride_runtime_api::RuntimeHandle::manifest`];
     * empty for legacy `.trd` archives without lights. iOS hosts
     * enumerate at load to build Filament light entities.
     */
    fun `listLights`(): List<TrideLightDescriptor>
    
    /**
     * Nodes drawn from a parametric datablock, in manifest order — linked
     * duplicates once per node. Their geometry: [`Self::datablock_mesh`] of the datablock.
     */
    fun `listParametricNodes`(): List<TrideParametricNode>
    
    /**
     * The node material palette `slug` draws with on `family` (`"mesh"` — a scene mesh,
     * `"generated"` — a generated mesh, `"instanced"` — clones and modules). `None` =
     * the built-in path: no graph, its codegen failed (logged at load), an unknown family,
     * or no object of the scene draws it on that family (the scene ships no package for it).
     */
    fun `materialGraph`(`slug`: kotlin.String, `family`: kotlin.String): TrideMaterialGraph?
    
    /**
     * Every graph material that draws a family through the built-in path — its record no longer
     * describes it, it was saved for another renderer version, or the scene does not hold its
     * package — by slug then family: tell the app once per material and code, in these words.
     */
    fun `materialGraphProblems`(): List<TrideMaterialGraphProblem>
    
    /**
     * Palette slugs an object of the scene draws through a node graph, in manifest
     * order — the slugs a host loads packages for with [`Self::material_graph`].
     */
    fun `materialGraphSlugs`(): List<kotlin.String>
    
    /**
     * The uniforms of `slug`'s `family` package at the scene's current values — pull after a
     * `/materialOverrides/{slug}/…` mutation. `objectSeed` is left to the host; a masked
     * material carries `maskThreshold`. Empty = the built-in path.
     */
    fun `materialGraphValues`(`slug`: kotlin.String, `family`: kotlin.String): List<TrideMaterialGraphValue>
    
    /**
     * Palette material `slug` as the scene draws it now — authored entry + the timeline /
     * binding writes to `/materialOverrides/{slug}/…`; a host calls it for the
     * slugs a tick's mutations touched and recolours every instance of that look. `None` when
     * the slug is unknown.
     */
    fun `materialParams`(`slug`: kotlin.String): TrideMaterialParams?
    
    /**
     * The node table's world matrices after the last tick: LE `f32`, 64 bytes per node,
     * column-major, nodes in `scene_record().nodes` order (empty when the scene's lock is
     * poisoned). A diagnostic for the host's check mode (gate A = B of E6): the host compares
     * the worlds its entities are drawn at with these; it does not call it to draw.
     */
    fun `nodeWorlds`(): kotlin.ByteArray
    
    /**
     * Every node under view point `(x, y)`, nearest first — empty without a
     * viewport, without a camera, or when no listener of the scene targets a node.
     */
    fun `pick`(`x`: kotlin.Float, `y`: kotlin.Float): List<TridePointerHit>
    
    /**
     * Queue a pointer event at `(x, y)` points from the view's top-left corner.
     * The scene picks what is under it and runs its listeners — taps, drags — on the next
     * [`Self::tick`]; their writes are visible from the tick after.
     *
     * # Errors
     * [`TrideError::Internal`] only on mutex poisoning.
     */
    fun `pointer`(`phase`: TridePointerPhase, `x`: kotlin.Float, `y`: kotlin.Float)
    
    /**
     * Read a property from the internal glTF document by JSON Pointer.
     *
     * Returns `None` (encoded as Swift `nil` / Kotlin `null`) if the
     * pointer doesn't resolve. The returned string is the
     * JSON-encoded value (e.g. `"1.5"`, `"[1.0, 0.0, 0.0]"`).
     */
    fun `readProperty`(`pointer`: kotlin.String): kotlin.String?
    
    /**
     * `true` while a source measured from the page's scroll is bound — report `scroll` then.
     */
    fun `readsScroll`(): kotlin.Boolean
    
    /**
     * Authored render settings (`manifest.render_settings`)
     * in normalized form — every default resolved by the schema, enums as
     * FFI variants — so a host applies them verbatim (no host-side `??`
     * defaults). `None` = not authored → the host keeps its
     * Filament defaults; `Some(default)` = explicitly "default quality"
     * (distinct from "not set").
     */
    fun `renderSettings`(): TrideRenderSettings?
    
    /**
     * The scene's render settings with the host's knobs applied, in the same
     * normalized form as [`Self::render_settings`]. No knob set → exactly
     * [`Self::render_settings`] (`None` stays `None`); a knob over a scene with no render
     * settings lays over the defaults.
     */
    fun `renderSettingsWith`(`overrides`: TrideRenderOverrides): TrideRenderSettings?
    
    /**
     * The next tick first hands out every value handed out before, and generators
     * announce again — for a host that lost its renderer state (a new surface).
     */
    fun `requestFullFrame`()
    
    /**
     * Preview reset: initial SM state, view-model defaults, the node table back to the
     * manifest's poses.
     * Uses the scene timeline position from the last [`Self::tick`] (`0` if never ticked).
     */
    fun `reset`()
    
    /**
     * Drop what `input` was given — a new track, another station; the format stays.
     *
     * # Errors
     * [`TrideError::InvalidAudio`] for an input that was never begun.
     */
    fun `resetAudio`(`input`: kotlin.String)
    
    /**
     * The host's tick loop runs again after standing still (the view off screen, the app in the
     * background): the scroll speed is measured afresh from the next [`Self::tick`] instead of
     * reading the page's move meanwhile as one frame's jump. Call it before that tick.
     *
     * # Errors
     * [`TrideError::Internal`] on mutex poisoning.
     */
    fun `resume`()
    
    /**
     * The scene record: nodes, materials per family, skins, lights, cameras,
     * images — the scene as loaded. `None` only when the scene's lock is poisoned.
     */
    fun `sceneRecord`(): TrideSceneRecord?
    
    /**
     * The host's page or scroll view, in points: how far it is scrolled (`offset`), the visible
     * height (`extent`), and where the scene sits in it (`scene_top`, `scene_height`). Call it
     * whenever any of them changes while a scroll source is bound ([`Self::bind_input`]); the
     * bound inputs read the scroll speed and the scene's pass through the view on the next
     * [`Self::tick`].
     *
     * # Errors
     * [`TrideError::InvalidScroll`] for a value that is not finite, an `extent` of 0 or less or a
     * negative `scene_height`; [`TrideError::Internal`] on mutex poisoning.
     */
    fun `scroll`(`offset`: kotlin.Double, `extent`: kotlin.Double, `sceneTop`: kotlin.Double, `sceneHeight`: kotlin.Double)
    
    /**
     * What sounds now — call it every frame before `tick`: `input` is heard at
     * `audible_time_s` of its audio time (a track: position minus the output latency), its
     * probes times `gain`.
     *
     * # Errors
     * [`TrideError::InvalidAudio`] for an input that was never begun or a time / gain that is
     * not finite.
     */
    fun `setAudioTime`(`input`: kotlin.String, `audibleTimeS`: kotlin.Double, `gain`: kotlin.Float)
    
    /**
     * Set a named view-model binding to the given typed value.
     *
     * # Errors
     * Returns [`TrideError::InvalidBinding`] when the name is unknown
     * or the value kind does not match the manifest declaration.
     */
    fun `setBinding`(`name`: kotlin.String, `value`: TrideValue)
    
    /**
     * Hand out only the mutations of channels that changed since the last tick handed
     * them out — the host keeps every value until it is written again. Off by default.
     */
    fun `setChangedOnly`(`enabled`: kotlin.Boolean)
    
    /**
     * Hand out `/node/{uid}/drawVisible` — each node's visibility to the renderer, its own flag
     * and every ancestor's — every node on the next tick, then the ones that changed (all again
     * after `reset` / `request_full_frame`). Off by default: the stream is what it was.
     */
    fun `setDrawVisibility`(`enabled`: kotlin.Boolean)
    
    /**
     * A picture of `width × height` px — decoded, downscaled to 2048 on the long side, EXIF-turned
     * — is in place on image input `name`: `loaded`, its revision (returned) one up. Keep the
     * pixels by `(name, revision)`; the next tick lays the picture over its fields.
     *
     * # Errors
     * [`TrideError::InvalidImage`] for a name that is no image input or a size outside 1…2048.
     */
    fun `setImage`(`name`: kotlin.String, `width`: kotlin.UInt, `height`: kotlin.UInt): kotlin.ULong
    
    /**
     * Write a batch of input values (`{"name": value, …}` as JSON) at once: all are checked,
     * the good ones land together for the next tick — with `strict` none unless all are good.
     * Returns the report as JSON `{"applied":[…],"rejected":[{name, code, message}],
     * "unknown":[…],"untouched":[…]}`.
     *
     * # Errors
     * [`TrideError::InvalidBinding`] when `values_json` is not a JSON object (nothing is
     * written); [`TrideError::Internal`] on mutex poisoning.
     */
    fun `setInputsJson`(`valuesJson`: kotlin.String, `strict`: kotlin.Boolean): kotlin.String
    
    /**
     * The host's view: its size in points and — only when it does not draw through
     * the scene's active camera — its own camera. Applies to every pointer event from now on.
     *
     * # Errors
     * [`TrideError::Internal`] only on mutex poisoning.
     */
    fun `setViewport`(`width`: kotlin.Float, `height`: kotlin.Float, `camera`: TrideHostCamera?)
    
    /**
     * Subscribe to B1 `manifest.events[]` emissions (preview log, host, …).
     * D2: callback receives (`name`, `payload`) only. Invoked on the
     * thread that calls `tick` / `emit_event`, after batched apply
     * (after batched apply).
     *
     * The listener is a `UniFFI` **callback interface**; foreign code
     * passes a `Box` — see `uniffi` 0.28 `FfiConverter` for `Box<dyn …>`.
     */
    fun `subscribeEvents`(`listener`: TrideOutgoingEventListener): TrideSubscriptionId
    
    /**
     * Subscribe to SM transitions of every layer, with the layer. Invoked on the
     * thread that calls `tick`, after batched apply.
     */
    fun `subscribeLayerStateChanges`(`listener`: TrideLayerStateChangeListener): TrideSubscriptionId
    
    /**
     * Subscribe to SM transitions after batched binding apply — every layer alike,
     * without the layer; prefer [`Self::subscribe_layer_state_changes`].
     */
    fun `subscribeStateChanges`(`listener`: TrideStateChangeListener): TrideSubscriptionId
    
    /**
     * Advance the scene by `dt_ms` milliseconds (relative to the
     * previous tick).
     *
     * The first call seeds the internal monotonic clock at zero; each
     * subsequent call advances by `dt_ms * 1_000_000` nanoseconds.
     * This mirrors how a host drives its render loop (delta-time per frame from
     * `CADisplayLink`).
     *
     * Negative or NaN deltas are clamped to zero (frame-time noise
     * from `CADisplayLink` should never produce them, but we defend
     * at the boundary).
     *
     * # Errors
     * Returns [`TrideError::Internal`] only on mutex poisoning
     * (should not happen in practice).
     */
    fun `tick`(`dtMs`: kotlin.Float): TickResult
    
    /**
     * Fire a one-shot trigger event (must be a `trigger`-kind view-model row).
     *
     * The trigger is consumed by the next [`tick`](Self::tick) call.
     *
     * # Errors
     * Returns [`TrideError::InvalidTrigger`] when the event name is
     * unknown or the named input is not a `trigger`.
     */
    fun `trigger`(`name`: kotlin.String)
    
    /**
     * Unbind input `input` — the host writes it again; it keeps its value. `true` when it was
     * bound.
     *
     * # Errors
     * [`TrideError::Internal`] on mutex poisoning.
     */
    fun `unbindInput`(`input`: kotlin.String): kotlin.Boolean
    
    /**
     * Unsubscribe a handle from [`Self::subscribe_events`] or [`Self::subscribe_state_changes`].
     */
    fun `unsubscribe`(`id`: TrideSubscriptionId): kotlin.Boolean
    
    /**
     * Unsubscribe (legacy name — same as [`Self::unsubscribe`]).
     */
    fun `unsubscribeEvents`(`id`: TrideSubscriptionId): kotlin.Boolean
    
    companion object
}

/**
 * Opaque handle to a single loaded Tride scene.
 *
 * Owns the parsed `.trd` archive, the compiled bindings engine, the
 * state machine, the mutable glTF document, the view-model value store, and
 * the fixed-step clock state. Cloned freely (cheap `Arc`); concurrent
 * access is serialised by an internal `Mutex` (see crate-level docs).
 *
 * The `last_tick_ns` field is the FFI-side translation of the
 * `dt_ms`-style API exposed to Swift / Kotlin into the monotonic
 * `now_ns` timeline that `tride-runtime-api::RuntimeHandle::tick`
 * expects. We keep it in this crate so that `tride-runtime-api`
 * stays untouched.
 */
open class TrideScene: Disposable, AutoCloseable, TrideSceneInterface {

    constructor(pointer: Pointer) {
        this.pointer = pointer
        this.cleanable = UniffiLib.CLEANER.register(this, UniffiCleanAction(pointer))
    }

    /**
     * This constructor can be used to instantiate a fake object. Only used for tests. Any
     * attempt to actually use an object constructed this way will fail as there is no
     * connected Rust object.
     */
    @Suppress("UNUSED_PARAMETER")
    constructor(noPointer: NoPointer) {
        this.pointer = null
        this.cleanable = UniffiLib.CLEANER.register(this, UniffiCleanAction(pointer))
    }

    protected val pointer: Pointer?
    protected val cleanable: UniffiCleaner.Cleanable

    private val wasDestroyed = AtomicBoolean(false)
    private val callCounter = AtomicLong(1)

    override fun destroy() {
        // Only allow a single call to this method.
        // TODO: maybe we should log a warning if called more than once?
        if (this.wasDestroyed.compareAndSet(false, true)) {
            // This decrement always matches the initial count of 1 given at creation time.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable.clean()
            }
        }
    }

    @Synchronized
    override fun close() {
        this.destroy()
    }

    internal inline fun <R> callWithPointer(block: (ptr: Pointer) -> R): R {
        // Check and increment the call counter, to keep the object alive.
        // This needs a compare-and-set retry loop in case of concurrent updates.
        do {
            val c = this.callCounter.get()
            if (c == 0L) {
                throw IllegalStateException("${this.javaClass.simpleName} object has already been destroyed")
            }
            if (c == Long.MAX_VALUE) {
                throw IllegalStateException("${this.javaClass.simpleName} call counter would overflow")
            }
        } while (! this.callCounter.compareAndSet(c, c + 1L))
        // Now we can safely do the method call without the pointer being freed concurrently.
        try {
            return block(this.uniffiClonePointer())
        } finally {
            // This decrement always matches the increment we performed above.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable.clean()
            }
        }
    }

    // Use a static inner class instead of a closure so as not to accidentally
    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val pointer: Pointer?) : Runnable {
        override fun run() {
            pointer?.let { ptr ->
                uniffiRustCall { status ->
                    UniffiLib.INSTANCE.uniffi_tride_ffi_fn_free_tridescene(ptr, status)
                }
            }
        }
    }

    fun uniffiClonePointer(): Pointer {
        return uniffiRustCall() { status ->
            UniffiLib.INSTANCE.uniffi_tride_ffi_fn_clone_tridescene(pointer!!, status)
        }
    }

    
    /**
     * Authored active camera slug (`manifest.scene.active_camera`).
