/**
 * @suppress
 */
public object FfiConverterTypeTrideScene: FfiConverter<TrideScene, Pointer> {

    override fun lower(value: TrideScene): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): TrideScene {
        return TrideScene(value)
    }

    override fun read(buf: ByteBuffer): TrideScene {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: TrideScene) = 8UL

    override fun write(value: TrideScene, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



/**
 * A host script replayed by [`TrideScene::advance`].
 */
data class AdvanceResult (
    /**
     * Final value of every pointer the script's ticks wrote — apply it like one tick.
     */
    var `tick`: TickResult, 
    /**
     * Ticks the script ran (the final geometry tick included).
     */
    var `ticks`: kotlin.ULong, 
    /**
     * Step the script stopped at (`until` out of time, a rejected input, unreadable JSON).
     */
    var `stoppedStep`: kotlin.UInt?, 
    /**
     * Why it stopped; `None` = it ran to the end.
     */
    var `stoppedReason`: kotlin.String?
) {
    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeAdvanceResult: FfiConverterRustBuffer<AdvanceResult> {
    override fun read(buf: ByteBuffer): AdvanceResult {
        return AdvanceResult(
            FfiConverterTypeTickResult.read(buf),
            FfiConverterULong.read(buf),
            FfiConverterOptionalUInt.read(buf),
            FfiConverterOptionalString.read(buf),
        )
    }

    override fun allocationSize(value: AdvanceResult) = (
            FfiConverterTypeTickResult.allocationSize(value.`tick`) +
            FfiConverterULong.allocationSize(value.`ticks`) +
            FfiConverterOptionalUInt.allocationSize(value.`stoppedStep`) +
            FfiConverterOptionalString.allocationSize(value.`stoppedReason`)
    )

    override fun write(value: AdvanceResult, buf: ByteBuffer) {
            FfiConverterTypeTickResult.write(value.`tick`, buf)
            FfiConverterULong.write(value.`ticks`, buf)
            FfiConverterOptionalUInt.write(value.`stoppedStep`, buf)
            FfiConverterOptionalString.write(value.`stoppedReason`, buf)
    }
}



/**
 * Per-tick eval diagnostic exposed through `UniFFI`.
 *
 * Rust is the source of truth, so bindings that fail to evaluate must be visible to platform
 * logs.
 */
data class EvalDiagnostic (
    var `kind`: EvalDiagnosticKind, 
    var `pointer`: kotlin.String, 
    var `message`: kotlin.String, 
