/**
 * Unified error type surfaced across the FFI boundary.
 *
 * `tride-runtime-api` exposes three distinct error enums (`LoadError`,
 * `InputError`, `TriggerError`); we collapse them into one
 * foreign-facing enum because Swift / Kotlin throwing functions
 * share a single error type per call site and a single FFI enum
 * keeps the bindings ergonomic. The original variant is preserved
 * in the `msg` field of every variant.
 */
sealed class TrideException(message: String): kotlin.Exception(message) {
        
    /**
     * `.trd` archive parse / schema / bindings / SM compile failure.
     */
        class LoadFailed(message: String) : TrideException(message)
        
    /**
     * The `.trd` was written by a newer Tride format and does not parse here: the file is fine,
     * the app is old — ask to update it rather than report a broken file. The
     * message names both format versions.
     */
        class NewerFormat(message: String) : TrideException(message)
        
    /**
     * Unknown view-model name or type mismatch on `setBinding` / `getBinding`.
     */
        class InvalidBinding(message: String) : TrideException(message)
        
    /**
     * Unknown event name or non-trigger kind on `trigger`.
     */
        class InvalidTrigger(message: String) : TrideException(message)
        
    /**
     * Internal runtime invariant violated (mutex poisoned, JSON encode
     * failure, …). Should never happen in practice; logged for
     * observability.
     */
        class Internal(message: String) : TrideException(message)
        
    /**
     * [`RuntimeHandle::emit_event`] / manifest `events[]` contract.
     */
        class OutgoingEvent(message: String) : TrideException(message)
        
    /**
     * A host audio call that cannot be applied: an input name that is no slug or was never
     * begun, a format without samples, a time or gain that is not finite.
     */
        class InvalidAudio(message: String) : TrideException(message)
        
    /**
     * A host picture call that cannot be applied: a name that is no image input, a size outside
     * 1…2048 px a side.
     */
        class InvalidImage(message: String) : TrideException(message)
        
    /**
     * A host scroll report that cannot be applied: a value that is not finite, a window height
     * of 0 or less, a negative scene height. The frame the scene had stays.
     */
        class InvalidScroll(message: String) : TrideException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<TrideException> {
        override fun lift(error_buf: RustBuffer.ByValue): TrideException = FfiConverterTypeTrideError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeTrideError : FfiConverterRustBuffer<TrideException> {
    override fun read(buf: ByteBuffer): TrideException {
        
            return when(buf.getInt()) {
            1 -> TrideException.LoadFailed(FfiConverterString.read(buf))
            2 -> TrideException.NewerFormat(FfiConverterString.read(buf))
            3 -> TrideException.InvalidBinding(FfiConverterString.read(buf))
            4 -> TrideException.InvalidTrigger(FfiConverterString.read(buf))
            5 -> TrideException.Internal(FfiConverterString.read(buf))
            6 -> TrideException.OutgoingEvent(FfiConverterString.read(buf))
            7 -> TrideException.InvalidAudio(FfiConverterString.read(buf))
            8 -> TrideException.InvalidImage(FfiConverterString.read(buf))
            9 -> TrideException.InvalidScroll(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: TrideException): ULong {
        return 4UL
    }

    override fun write(value: TrideException, buf: ByteBuffer) {
        when(value) {
            is TrideException.LoadFailed -> {
                buf.putInt(1)
                Unit
            }
            is TrideException.NewerFormat -> {
                buf.putInt(2)
                Unit
            }
            is TrideException.InvalidBinding -> {
                buf.putInt(3)
                Unit
            }
            is TrideException.InvalidTrigger -> {
                buf.putInt(4)
                Unit
            }
            is TrideException.Internal -> {
                buf.putInt(5)
                Unit
            }
            is TrideException.OutgoingEvent -> {
                buf.putInt(6)
                Unit
            }
            is TrideException.InvalidAudio -> {
                buf.putInt(7)
                Unit
            }
            is TrideException.InvalidImage -> {
                buf.putInt(8)
                Unit
            }
            is TrideException.InvalidScroll -> {
                buf.putInt(9)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



