/**
 * Typed mutation payload — eliminates JSON encode/decode overhead per tick.
 *
 * Swift codegen produces a tagged enum:
 * ```swift
 * public enum TrideTypedValue {
 * case scalar(value: Double)
 * case vec3(x: Double, y: Double, z: Double)
 * case quat(x: Double, y: Double, z: Double, w: Double)
 * case color(r: Double, g: Double, b: Double, a: Double)
 * case boolValue(value: Bool)
 * case stringValue(value: String)
 * case json(raw: String)
 * }
 * ```
 */
sealed class TrideTypedValue {
    
    /**
     * Floating-point scalar (single number property).
     */
    data class Scalar(
        val `value`: kotlin.Double) : TrideTypedValue() {
        companion object
    }
    
    /**
     * Three-component vector (translation, scale).
     */
    data class Vec3(
        val `x`: kotlin.Double, 
        val `y`: kotlin.Double, 
        val `z`: kotlin.Double) : TrideTypedValue() {
        companion object
    }
    
    /**
     * Unit quaternion `[x, y, z, w]` (canonical rotation).
     */
    data class Quat(
        val `x`: kotlin.Double, 
        val `y`: kotlin.Double, 
        val `z`: kotlin.Double, 
        val `w`: kotlin.Double) : TrideTypedValue() {
        companion object
    }
    
    /**
     * RGBA color `[r, g, b, a]`.
     */
    data class Color(
        val `r`: kotlin.Double, 
        val `g`: kotlin.Double, 
        val `b`: kotlin.Double, 
        val `a`: kotlin.Double) : TrideTypedValue() {
        companion object
    }
    
    /**
     * Boolean property.
     */
    data class BoolValue(
        val `value`: kotlin.Boolean) : TrideTypedValue() {
        companion object
    }
    
    /**
     * String property.
     */
    data class StringValue(
        val `value`: kotlin.String) : TrideTypedValue() {
        companion object
    }
    
    /**
     * Fallback: raw JSON for shapes not yet covered by typed variants.
     */
    data class Json(
        val `raw`: kotlin.String) : TrideTypedValue() {
        companion object
    }
    

    
    companion object
}

